import numpy as np
def build(B):
    blocks=[]
    for r in range(3):
        row=[]
        for c in range(3):
            M=B
            if c%2: M=np.fliplr(M)
            if r%2: M=np.flipud(M)
            row.append(M)
        return np.block([[np.flipud(np.fliplr(B) if c%2 else B) if r%2 else (np.fliplr(B) if c%2 else B) for c in range(3)] for r in range(3)])
def dihedrals(I):
    out={}
    for name,M in [('I',I),('fh',np.fliplr(I)),('fv',np.flipud(I)),('r180',I[::-1,::-1]),
                   ('T',I.T),('Tfh',np.fliplr(I.T)),('Tfv',np.flipud(I.T)),('Tr180',I.T[::-1,::-1])]:
        out[name]=M
    return out
syms = {'transpose': lambda A: A.T, 'anti': lambda A: np.fliplr(A.T), 'rot180': lambda A: A[::-1,::-1],
